const STORAGE_KEY='patentino-academy-v1';
const safeLoad=()=>{try{return JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}catch{return {}}};
const saved=safeLoad();
const data={completed:saved.completed||[],bookmarks:saved.bookmarks||[],wrong:saved.wrong||[],notes:saved.notes||{},generalNotes:saved.generalNotes||'',flashKnown:saved.flashKnown||[],flashAgain:saved.flashAgain||[],quizHistory:saved.quizHistory||[],examHistory:saved.examHistory||[],officialDone:saved.officialDone||[],lastLesson:saved.lastLesson||null};
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const allLessons=MODULES.filter(m=>m.id!=='cremona').flatMap(m=>m.lessons.map((l,i)=>({...l,mid:m.id,idx:i,category:m.category,moduleTitle:m.title,id:`${m.id}:${i}`})));
const lessonBy=(mid,i)=>MODULES.find(m=>m.id===mid)?.lessons[Number(i)];
const moduleBy=id=>MODULES.find(m=>m.id===id);
const rand=a=>[...a].sort(()=>Math.random()-.5);
const shuffle=a=>{const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b};
const save=()=>{try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}catch{toast('Impossibile salvare sul dispositivo')}};
const len=allLessons.length;
const pct=()=>Math.round(data.completed.filter(id=>allLessons.some(l=>l.id===id)).length/len*100);
const tag=(txt,cls='')=>`<span class="pill ${cls}">${esc(txt)}</span>`;
const btn=(txt,action,cls='btn-primary',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${txt}</button>`;
const iconArrow='↗';
const categoryLabel=c=>c==='normativa'?'Parte normativa':'Parte tecnica';
const sectorTag=m=>tag(sectorName(m),sectorOf(m)==='diritto'?'':sectorOf(m)==='economia'?'blue':'gray');
const external=(url,text,cls='btn btn-outline btn-sm')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`;
let libraryFilter='all',libraryQuery='',quizSubject='all',quizModule='all',quizOrigin='milano',quizSize=10,quizSession=null,examSession=null,flashCategory='all',flashIndex=0,flashFlipped=false,reviewTab='errors',archiveFilter='all',officialSessionId='149';
let milanoSearch='',milanoTopic='all',milanoMode='all',milanoPage=0;
