function currentRoute(){let a=decodeURIComponent((location.hash||'#/home').slice(2)).split('/');return {view:a[0]||'home',id:a[1],idx:a[2]};}
function navigate(view,id,idx){const target='#/'+[view,id,idx].filter(v=>v!==undefined).join('/');if(location.hash===target){render()}else{location.hash=target}}
function navActive(view){document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===view||(view==='module'||view==='lesson')&&x.dataset.nav==='library'));const names={home:'Panoramica',library:'Il programma',module:'Il programma',lesson:'Lezione',quiz:'Allenamento quiz',exam:'Simulazione d’esame',flashcards:'Flashcard',review:'Ripasso & appunti',sources:'Fonti ufficiali',archive:'Banche quiz ufficiali',officialtest:'Quiz ufficiale Roma',milanobank:'Banca ufficiale Milano'};$('#breadcrumb').innerHTML=`La tua accademia <span>›</span> ${names[view]||'Panoramica'}`;$('.nav-mini').textContent=MODULES.length-1;$('#sidebar-percent').textContent=pct()+'%';$('#sidebar-progress-fill').style.width=pct()+'%';const done=data.completed.filter(id=>!id.startsWith('cremona:')).length;$('#sidebar-completed').textContent=done+(done===1?' lezione completata':' lezioni completate');}
function pageTitle(label,title,description,action=''){return `<div class="page-header"><div><div class="eyebrow">${esc(label)}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function heroSvg(){return `<svg class="hero-building" viewBox="0 0 260 235" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M20 201V92L124 30L230 92V201" stroke="#A9CAB1" stroke-width="2"/><path d="M6 98L124 19L246 98" stroke="#D9ED99" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M48 202V105H202V202" stroke="#A9CAB1" stroke-width="2"/><path d="M94 202V138H153V202" stroke="#A9CAB1" stroke-width="2"/><path d="M110 153V178M135 153V178" stroke="#A9CAB1" stroke-width="2"/><rect x="60" y="124" width="23" height="30" stroke="#D9ED99" stroke-width="2"/><rect x="168" y="124" width="23" height="30" stroke="#D9ED99" stroke-width="2"/><path d="M20 202H230M73 36V22H99" stroke="#A9CAB1" stroke-width="2"/><path d="M48 175H94M153 175H202" stroke="#719989" stroke-width="2"/><circle cx="124" cy="85" r="13" stroke="#D9ED99" stroke-width="2"/><path d="M111 85H137M124 72V98" stroke="#D9ED99" stroke-width="2"/></svg>`;}
function renderHome(){const recommended=[...allLessons.filter(l=>sectorOf(moduleBy(l.mid))==='diritto'),...allLessons.filter(l=>sectorOf(moduleBy(l.mid))==='immobiliare'),...allLessons.filter(l=>sectorOf(moduleBy(l.mid))==='economia')];const next=recommended.find(l=>!data.completed.includes(l.id))||recommended[0];const completedCategories={normativa:allLessons.filter(l=>l.category==='normativa'&&data.completed.includes(l.id)).length,tecnica:allLessons.filter(l=>l.category==='tecnica'&&data.completed.includes(l.id)).length};const latest=data.examHistory.at(-1);return `
 <div class="hero"><div><div class="hero-top"><i class="live-dot"></i><span>IL TUO PERCORSO COMINCIA QUI</span></div><h1>Da zero a<br><em>agente immobiliare.</em></h1><p>Un argomento alla volta, senza dare nulla per scontato. Studia, mettiti alla prova e arriva all'esame con metodo.</p><button class="btn btn-lime" data-open-lesson="${next.mid}|${next.idx}">${data.completed.length?'Continua a studiare':'Inizia il percorso'} <span>↗</span></button></div><div class="hero-art"><div class="hero-circle"></div>${heroSvg()}<div class="hero-floating"><b>✓</b> Un passo alla volta</div><div class="hero-floating second"><b>✦</b> Ci sei quasi!</div></div></div>
 <div class="metrics"><div class="metric"><div class="metric-top">Lezioni completate <span class="metric-symbol">▤</span></div><div class="metric-number">${data.completed.filter(id=>allLessons.some(l=>l.id===id)).length}<span class="muted" style="font-size:15px">/${len}</span></div><div class="metric-caption">Il tuo programma</div></div><div class="metric"><div class="metric-top">Argomenti <span class="metric-symbol">▦</span></div><div class="metric-number">${MODULES.length-1}</div><div class="metric-caption">Immobiliare · Diritto · Economia</div></div><div class="metric"><div class="metric-top">Quiz svolti <span class="metric-symbol">◉</span></div><div class="metric-number">${data.quizHistory.reduce((a,x)=>a+x.count,0)+data.examHistory.reduce((a,x)=>a+x.count,0)}</div><div class="metric-caption">Risposte allenate</div></div><div class="metric"><div class="metric-top">Da ripassare <span class="metric-symbol">◇</span></div><div class="metric-number">${data.wrong.length}</div><div class="metric-caption">Errori da superare</div></div></div>
 <div class="section-heading"><div><h2>Il tuo prossimo passo</h2><p>Partiamo dalle basi, poi costruiamo tutto il resto.</p></div>${btn('Tutto il programma ↗','go-library','btn-outline btn-sm')}</div>
 <div class="study-banner" style="margin-bottom:22px"><div><b>Il programma in tre settori</b><p>Immobiliare per la parte tecnica e l’estimo; Diritto per norme, contratti e rapporti giuridici; Economia per tributi, impresa e finanza. La simulazione conserva le due prove ufficiali, normativa e tecnica.</p></div><button class="btn btn-primary btn-sm" data-action="go-library">Esplora i tre settori →</button></div>
 <div class="dashboard-grid"><div class="panel" style="padding:18px;display:grid;gap:10px"><div class="learning-card" data-open-lesson="${next.mid}|${next.idx}" role="button" tabindex="0"><div class="learning-icon">▤</div><div><h4>${esc(next.title)}</h4><p>${esc(next.moduleTitle)} · 8 minuti di lettura</p></div><span class="learning-arrow">→</span></div><div class="learning-card" data-nav="quiz" role="button" tabindex="0"><div class="learning-icon" style="background:#fff4e5;color:#ab813e">◉</div><div><h4>Allenamento guidato</h4><p>Quiz con spiegazioni e archivio errori</p></div><span class="learning-arrow">→</span></div><div class="learning-card" data-nav="flashcards" role="button" tabindex="0"><div class="learning-icon" style="background:#edf1fb;color:#6281b2">▣</div><div><h4>Ripasso attivo</h4><p>Flashcard sui concetti fondamentali</p></div><span class="learning-arrow">→</span></div></div><div class="exam-box"><div><div class="eyebrow">COME FUNZIONA L’ESAME</div><h3>Conosci il tuo obiettivo.</h3><p>Per la sede camerale di Milano, accessibile ai candidati di Cremona tramite convenzione, la prova scritta è al computer.</p></div><div><div class="exam-spec"><div><b>40</b><span>domande in totale</span></div><div><b>40'</b><span>tempo massimo</span></div><div><b>20+20</b><span>normativa e tecnica</span></div><div><b>7/10</b><span>media per passare all’orale*</span></div></div><button class="btn btn-primary" data-nav="exam">Prova una simulazione →</button></div><small style="display:block;color:#86978b;margin-top:14px">* Con almeno 6/10 in ciascuna parte. Orale: almeno 6/10.</small></div></div>
 <div class="section-heading"><div><h2>Le prove dell’esame</h2><p>Lo studio è diviso in tre settori, ma le prove scritte valutano normativa e tecnica.</p></div></div><div class="two-col"><div class="summary-card"><div class="eyebrow">01 / MATERIA GIURIDICA</div><h3>Parte normativa</h3><p style="font-size:12px;color:#708778;line-height:1.8">Mediatore, diritto civile, contratti, compravendita, fisco, successioni, società e obblighi professionali.</p><div class="mini-steps">${['Contratti','Diritto civile','Fisco','Professione'].map(x=>`<span class="step-tag">${x}</span>`).join('')}</div><p style="margin-top:19px;font-size:11px;color:#60816a">${completedCategories.normativa} lezioni completate</p><button class="btn btn-outline btn-sm" data-filter-category="normativa">Esplora normativa →</button></div><div class="summary-card" style="background:#f0f2f8;border-color:#e5e9f1"><div class="eyebrow" style="color:#7782a1">02 / MATERIA TECNICA</div><h3>Parte tecnica</h3><p style="font-size:12px;color:#77849b;line-height:1.8">Catasto, pubblicità immobiliare, urbanistica, condominio, estimo, mutui, edilizia e mercato.</p><div class="mini-steps">${['Catasto','Estimo','Urbanistica','Mutui'].map(x=>`<span class="step-tag" style="background:#e4eaf5;color:#7685a4">${x}</span>`).join('')}</div><p style="margin-top:19px;font-size:11px;color:#6c829d">${completedCategories.tecnica} lezioni completate</p><button class="btn btn-outline btn-sm" data-filter-category="tecnica">Esplora tecnica →</button></div></div>
 <div class="section-heading"><div><h2>Un piano per partire da zero</h2><p>Se studi con regolarità, puoi usare queste sei settimane come traccia orientativa.</p></div></div><div class="module-grid">${[
  ['01','Le fondamenta','Professione, diritto civile e diritti reali.','professione'],
  ['02','Impara i contratti','Obbligazioni, proposta, vendita, preliminare, locazioni.','contratti'],
  ['03','Norme e imposte','Successioni, società, fisco, antiriciclaggio.','fisco'],
  ['04','Conosci gli immobili','Catasto, registri, urbanistica, condominio, edifici.','catasto'],
  ['05','Impara a valutare','Estimo, superfici, rendimenti, mutui e mercato.','estimo'],
  ['06','Diventa pronto all’esame','Quiz misti, simulazioni da 40 minuti e orale.','orale']
 ].map(([n,t,d,id])=>`<article class="module-card" style="min-height:155px;padding:19px" data-open-module="${id}" role="button" tabindex="0"><div class="module-num">SETTIMANA ${n}</div><h3 style="margin:15px 0 7px">${t}</h3><p style="margin-bottom:0">${d}</p></article>`).join('')}</div>
 ${latest?`<div class="study-banner" style="margin-top:25px"><div><b>Ultima simulazione: ${latest.passed?'obiettivo raggiunto':'da migliorare'}</b><p>Normativa ${latest.n}/10 · Tecnica ${latest.t}/10 · ${new Date(latest.date).toLocaleDateString('it-IT')}</p></div><button class="btn btn-sm btn-outline" data-nav="exam">Riprova →</button></div>`:''}`;
}
function renderLibrary(){const filtered=MODULES.filter(m=>m.id!=='cremona'&&(libraryFilter==='all'||sectorOf(m)===libraryFilter)&&(`${m.title} ${m.description} ${m.lessons.map(l=>l.title).join(' ')}`).toLowerCase().includes(libraryQuery.toLowerCase()));return `${pageTitle('IL PROGRAMMA COMPLETO','Tre settori, un obiettivo.',`${MODULES.length-1} macro-argomenti d’esame e ${len} lezioni guidate. La divisione in Immobiliare, Diritto ed Economia è didattica; lo scritto camerale rimane suddiviso in normativa e tecnica.`)}
 <div class="study-banner"><div><b>Il percorso giusto per cominciare</b><p>Inizia dalle basi di diritto, poi passa a contratti, immobili, estimo e fiscalità. In ogni settore puoi aprire schemi, esempi e domande per l’orale.</p></div><button class="btn btn-primary btn-sm" data-open-lesson="civile|0">Parti dalle basi di Diritto →</button></div>
 <div class="sector-grid">${THEORY_SECTORS.map(s=>`<button class="sector-card ${libraryFilter===s.id?'selected':''}" data-lib-filter="${s.id}"><span class="sector-symbol">${s.icon}</span><strong>${s.name}</strong><span>${s.description}</span><small>${MODULES.filter(m=>m.id!=='cremona'&&sectorOf(m)===s.id).length} moduli</small></button>`).join('')}</div>
 <div class="filters"><button class="chip ${libraryFilter==='all'?'active':''}" data-lib-filter="all">Tutti i settori</button>${THEORY_SECTORS.map(s=>`<button class="chip ${libraryFilter===s.id?'active':''}" data-lib-filter="${s.id}">${s.name}</button>`).join('')}<div class="search-field" style="margin-left:auto;min-width:200px"><span>⌕</span><input id="module-search" placeholder="Cerca argomento..." value="${esc(libraryQuery)}"></div></div>
 ${THEORY_SECTORS.filter(s=>libraryFilter==='all'||libraryFilter===s.id).map(s=>{const items=filtered.filter(m=>sectorOf(m)===s.id);return items.length?`<div class="section-heading sector-heading"><div><div class="eyebrow">SETTORE · ${s.name.toUpperCase()}</div><h2>${s.name}</h2><p>${s.description}</p></div></div><div class="module-grid">${items.map(m=>{const done=m.lessons.filter((_,idx)=>data.completed.includes(`${m.id}:${idx}`)).length;return `<article class="module-card" data-open-module="${m.id}" tabindex="0" role="button"><div class="module-card-top"><span class="module-num">MODULO ${String(MODULES.indexOf(m)+1).padStart(2,'0')}</span><span class="module-symbol">${m.icon}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="module-footer"><span>${sectorTag(m)} ${tag(categoryLabel(m.category),m.category==='normativa'?'':'blue')}</span><span>${done}/${m.lessons.length} lezioni</span><div class="tiny-track"><span style="width:${done/m.lessons.length*100}%"></span></div></div></article>`}).join('')}</div>`:''}).join('')}${filtered.length?'':'<div class="empty-state">Nessun argomento trovato.</div>'}
 <div class="study-banner" style="margin-top:30px"><div><b>Approfondimento territoriale facoltativo: Cremona</b><p>Non è un settore dell’esame e non compare nelle simulazioni. Puoi consultare separatamente esempi locali su PGT, zone OMI e locazioni, utili per il lavoro quotidiano.</p></div><button class="btn btn-outline btn-sm" data-open-module="cremona">Apri l’approfondimento ↗</button></div>`;}
function renderModule(id){const m=moduleBy(id);if(!m)return notFound();const done=m.lessons.filter((_,i)=>data.completed.includes(`${id}:${i}`)).length;return `<button class="back-button" data-nav="library">← Torna al programma</button><div class="module-hero"><div>${tag(categoryLabel(m.category),m.category==='normativa'?'':'blue')}<h1>${esc(m.title)}</h1><p>${esc(m.description)}</p><div class="mini-steps"><span class="step-tag">${m.lessons.length} lezioni</span><span class="step-tag">${done} completate</span></div></div><div class="module-symbol" style="width:74px;height:74px;font-size:40px;flex-shrink:0">${m.icon}</div></div>
 <div class="section-heading"><div><h2>Lezioni del modulo</h2><p>Leggile nell’ordine o apri direttamente il punto che ti serve.</p></div></div><div class="lesson-list">${m.lessons.map((l,i)=>{const yes=data.completed.includes(`${m.id}:${i}`);return `<button class="lesson-row" data-open-lesson="${m.id}|${i}"><span class="lesson-row-num" style="${yes?'background:#e4f2df;color:#3b885e':''}">${yes?'✓':String(i+1).padStart(2,'0')}</span><span class="lesson-row-main"><h4>${esc(l.title)}</h4><p>${esc(l.intro)}</p></span><span class="lesson-row-end">→</span></button>`}).join('')}</div>
 <div class="two-col" style="margin-top:25px"><div class="summary-card"><h3>Schema da memorizzare</h3><div class="summary-list">${m.summary.map((s,i)=>`<div class="summary-item"><span>${i+1}</span>${esc(s)}</div>`).join('')}</div></div><div class="panel"><h3>Domande da orale</h3><p class="muted" style="font-size:11px;line-height:1.8">Quando avrai completato il modulo, prova a rispondere a voce alta senza leggere.</p><ol style="font-size:12px;line-height:2;color:#556a5e;padding-left:17px">${m.oral.map(q=>`<li>${esc(q)}</li>`).join('')}</ol><div class="module-mini-quiz"><b>Mini-quiz del modulo</b><p>Una verifica rapida, con correzione e spiegazioni dopo ogni risposta. Quesiti rielaborati dai temi camerali, quando disponibili.</p><button class="btn btn-primary btn-sm" data-mini-quiz="${m.id}">Inizia mini-quiz · ${Math.min(5,QUESTIONS.filter(q=>q.module===m.id&&['milano','roma'].includes(questionOrigin(q))).length||QUESTIONS.filter(q=>q.module===m.id).length)} domande →</button></div>${btn('Allenati sui quiz →','quiz-module','btn-primary btn-sm',`data-module-id="${m.id}"`)}</div></div>`;}
function renderLesson(id,index){const m=moduleBy(id),l=lessonBy(id,index);if(!m||!l)return notFound();const indexNum=Number(index),lid=`${id}:${indexNum}`,done=data.completed.includes(lid),marked=data.bookmarks.includes(lid),next=indexNum<m.lessons.length-1?{id,idx:indexNum+1}:MODULES[MODULES.indexOf(m)+1]&&MODULES[MODULES.indexOf(m)+1].id!=='cremona'?{id:MODULES[MODULES.indexOf(m)+1].id,idx:0}:null;data.lastLesson=lid;save();return `<button class="back-button" data-open-module="${id}">← Torna a ${esc(m.title)}</button><div class="lesson-layout"><article class="lesson-article"><div class="tag-list">${tag(categoryLabel(m.category),m.category==='normativa'?'':'blue')}${tag(`Lezione ${indexNum+1} di ${m.lessons.length}`)}${done?tag('✓ Completata'):''}</div><h1>${esc(l.title)}</h1><p class="lesson-lead">${esc(l.intro)}</p><div class="article-section"><div class="eyebrow">SPIEGAZIONE</div><h3>Capire il concetto</h3><p>${esc(l.detail)}</p></div><div class="note-box"><strong>✦ Esempio pratico</strong><p>${esc(l.example)}</p></div><div class="note-box warning"><strong>⚠ Attenzione all’esame</strong><p>${esc(l.mistake)}</p></div><div class="article-section"><div class="eyebrow">IN 10 SECONDI</div><h3>Da ricordare</h3><div class="formula">${esc(l.key)}</div></div><div class="article-toolbar"><button class="btn ${done?'btn-soft':'btn-primary'}" data-toggle-complete="${lid}">${done?'✓ Lezione completata':'✓ Segna come studiata'}</button><button class="btn btn-outline" data-toggle-bookmark="${lid}">${marked?'★ Nei preferiti':'☆ Salva per ripassare'}</button></div><div style="display:flex;justify-content:space-between;gap:10px;margin-top:38px;border-top:1px solid var(--border);padding-top:23px"><button class="btn btn-outline btn-sm" data-open-module="${id}">← Modulo</button>${next?`<button class="btn btn-primary btn-sm" data-open-lesson="${next.id}|${next.idx}">Prossima lezione →</button>`:`<button class="btn btn-primary btn-sm" data-nav="quiz">Passa ai quiz →</button>`}</div></article><div class="lesson-aside"><div class="aside-box"><div class="eyebrow">IL MODULO</div><h4>${esc(m.title)}</h4><div style="display:grid;gap:8px">${m.lessons.map((x,i)=>`<button class="btn btn-sm ${indexNum===i?'btn-soft':'btn-outline'}" style="white-space:normal;text-align:left;justify-content:flex-start" data-open-lesson="${id}|${i}">${data.completed.includes(`${id}:${i}`)?'✓':`${i+1}.`} ${esc(x.title)}</button>`).join('')}</div></div><div class="aside-box"><h4>Schema rapido</h4><ul>${m.summary.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div><div class="aside-box review-note"><label for="lesson-note">I tuoi appunti</label><p>Scrivi ciò che vuoi ricordare. Rimarrà salvato su questo dispositivo.</p><textarea id="lesson-note" data-note-lesson="${lid}" placeholder="Un dubbio, una definizione, un esempio...">${esc(data.notes[lid]||'')}</textarea></div></div></div>`;}
function questionOrigin(q){return q.origin||(q.official?'milano':'original')}
function categoryQuestions(subject,module,origin){return QUESTIONS.filter(q=>(origin==='cremona'||questionOrigin(q)!=='cremona')&&(subject==='all'||moduleBy(q.module).category===subject)&&(module==='all'||q.module===module)&&(origin==='all'||(origin==='official'?['milano','roma','venezia-rovigo'].includes(questionOrigin(q)):questionOrigin(q)===origin)));}
function renderQuiz(){if(quizSession)return renderQuizGame();const available=categoryQuestions(quizSubject,quizModule,quizOrigin);return `${pageTitle('ESERCITATI SENZA PRESSIONE','Allenamento quiz.','Rispondi, leggi la spiegazione e conserva automaticamente le domande sbagliate per il ripasso. Ogni quesito è a risposta singola.')}
 <div class="milano-intro"><strong>Milano: ${MILANO_TRACES.length} tracce originali nel manuale</strong><p><b>${MILANO_VERIFIED_TOTAL}</b> sono disponibili con tre risposte alternative, correzione motivata e riferimento per la verifica. Le altre <b>${MILANO_UNVERIFIED_TOTAL}</b> sono consultabili nell’archivio delle domande pubblicate: non attribuiamo loro una risposta senza verifica. Le opzioni e le soluzioni sono redatte per l’allenamento, non sono fornite dalla Camera.</p><div style="margin-top:13px"><button class="btn btn-primary btn-sm" data-nav="milanobank">Apri tutte le domande di Milano →</button></div></div>
 <section class="official-training-panel"><div class="eyebrow">NUOVA MODALITÀ · DOMANDE CAMERALI ORIGINALI</div><h2>1.545 quesiti ufficiali di Roma, qui nell’allenamento.</h2><p>Scegli una delle 35 batterie e svolgi il questionario della Camera di Commercio direttamente dentro il manuale. Sono domande storiche del 2014; la correzione è gestita dal sito camerale, non dalle statistiche dell’allenamento interno.</p><div class="official-training-controls"><label for="official-session-select">Batteria di domande</label><select id="official-session-select">${OFFICIAL_ARCHIVE_GROUPS.map(group=>`<optgroup label="${esc(group.title)}">${OFFICIAL_ARCHIVE_TESTS.filter(t=>t.groupId===group.id).map(t=>`<option value="${t.sourceId}" ${officialSessionId===String(t.sourceId)?'selected':''}>${esc(t.title)} · ${t.count} domande</option>`).join('')}</optgroup>`).join('')}</select><button class="btn btn-primary" data-action="start-official-quiz">Svolgi la batteria originale →</button></div><div class="official-training-footer"><span>${data.officialDone.length} su 35 batterie segnate come svolte</span><button class="btn btn-outline btn-sm" data-nav="archive">Vedi tutte le batterie</button></div></section>
 <div class="mode-cards"><div class="mode-card ${quizSize===10?'selected':''}" data-quiz-size="10"><div style="font-size:25px;margin-bottom:12px">⚡</div><b>Allenamento rapido</b><p>10 domande. Ideale anche per una pausa breve.</p></div><div class="mode-card ${quizSize===20?'selected':''}" data-quiz-size="20"><div style="font-size:25px;margin-bottom:12px">◎</div><b>Ripasso approfondito</b><p>20 domande, feedback subito dopo ogni risposta.</p></div><div class="mode-card ${quizSize===50?'selected':''}" data-quiz-size="50"><div style="font-size:25px;margin-bottom:12px">▦</div><b>Maratona da 50</b><p>50 quesiti, per consolidare diverse materie.</p></div><div class="mode-card ${quizSize==='errors'?'selected':''}" data-quiz-size="errors"><div style="font-size:25px;margin-bottom:12px">◇</div><b>Solo i miei errori</b><p>Riprova i quesiti che hai sbagliato in passato.</p></div></div>
 <div class="selector-panel" style="margin-top:18px"><h3>Personalizza la sessione</h3><div class="selector-grid"><div><label for="quiz-subject">Area</label><select id="quiz-subject"><option value="all" ${quizSubject==='all'?'selected':''}>Normativa + tecnica</option><option value="normativa" ${quizSubject==='normativa'?'selected':''}>Solo normativa</option><option value="tecnica" ${quizSubject==='tecnica'?'selected':''}>Solo tecnica</option></select></div><div><label for="quiz-module">Argomento</label><select id="quiz-module"><option value="all">Tutti gli argomenti</option>${MODULES.filter(m=>quizSubject==='all'||m.category===quizSubject).map(m=>`<option value="${m.id}" ${quizModule===m.id?'selected':''}>${esc(m.title)}</option>`).join('')}</select></div><div><label for="quiz-origin">Origine dei quesiti</label><select id="quiz-origin"><option value="all" ${quizOrigin==='all'?'selected':''}>Tutti i quesiti</option><option value="official" ${quizOrigin==='official'?'selected':''}>Milano + Roma + Venezia/Rovigo (rielaborati)</option><option value="milano" ${quizOrigin==='milano'?'selected':''}>Milano: tracce pubblicate e quiz rielaborati</option><option value="roma" ${quizOrigin==='roma'?'selected':''}>Solo Roma (archivio storico rielaborato)</option><option value="venezia-rovigo" ${quizOrigin==='venezia-rovigo'?'selected':''}>Venezia/Rovigo (banca storica rielaborata)</option><option value="cremona" ${quizOrigin==='cremona'?'selected':''}>Focus Cremona (casi locali)</option><option value="original" ${quizOrigin==='original'?'selected':''}>Originali di allenamento</option></select></div><div><label>Domande disponibili</label><div style="padding:13px;border:1px solid var(--border);border-radius:9px;color:#6c8876;font-size:12px;font-weight:700">${quizSize==='errors'?available.filter(q=>data.wrong.includes(q.id)).length:available.length} quesiti</div></div></div><div style="display:flex;align-items:center;gap:13px;flex-wrap:wrap">${btn('Inizia l’allenamento →','start-quiz')}${tag('Risposte spiegate')}${tag('Senza timer','blue')}</div></div>
 <div class="study-banner" style="margin-top:22px"><div><b>Quiz camerali: Milano, Roma e Venezia Rovigo</b><p>I quiz di Milano, Roma e Venezia Rovigo sono rielaborazioni didattiche di tracce e raccolte camerali, con alternative e spiegazioni riscritte. Le raccolte di Roma e Venezia Rovigo sono storiche: verifica le norme vigenti. Cremona è esclusa da tutti gli allenamenti generali e dalle simulazioni. I suoi casi locali sono accessibili soltanto selezionando esplicitamente «Focus Cremona».</p></div><div style="display:grid;gap:7px">${external(OFFICIAL_BANK_URL,'Banca Milano')}<button class="btn btn-primary btn-sm" data-nav="archive">Tutte le batterie ufficiali →</button></div></div>`;}
function renderQuizGame(){const g=quizSession;if(g.i>=g.questions.length)return renderQuizResult();const q=g.questions[g.i],sel=g.answers[g.i],finished=sel!==null,count=g.answers.filter(x=>x!==null).length;return `<div class="quiz-stage"><button class="back-button" data-action="quit-quiz">← Termina allenamento</button><div class="question-top"><div><div class="eyebrow">ALLENAMENTO GUIDATO</div><h2 style="font-size:19px;margin:0">Domanda ${g.i+1} <span class="muted">/ ${g.questions.length}</span></h2></div>${tag(categoryLabel(moduleBy(q.module).category),moduleBy(q.module).category==='normativa'?'':'blue')}</div><div class="quiz-meter"><span style="width:${(g.i+1)/g.questions.length*100}%"></span></div>${questionCard(q,sel,true)}<div class="quiz-controls"><span class="muted" style="font-size:11px">${count} ${count===1?'risposta data':'risposte date'}</span><button class="btn btn-primary" data-action="quiz-next" ${!finished?'disabled':''}>${g.i===g.questions.length-1?'Vedi il risultato':'Prossima domanda →'}</button></div></div>`;}
function questionCard(q,selected,training){const answered=selected!==null,origin=questionOrigin(q);const badge={milano:q.authenticStem?'Milano · testo originale; opzioni didattiche':'Milano · traccia rielaborata',roma:'Roma · archivio rielaborato', 'venezia-rovigo':'Venezia/Rovigo · banca rielaborata',cremona:'Focus Cremona · caso locale',original:'Esercizio originale'}[origin];return `<div class="question-card"><div class="question-top"><small>${esc(moduleBy(q.module).title).toUpperCase()}</small>${tag(badge,origin==='cremona'?'yellow':origin==='original'?'gray':'official')}</div><h2>${esc(q.question)}</h2><div class="choices">${q.options.map((o,i)=>`<button class="choice ${selected===i?'selected':''} ${training&&answered&&i===q.answer?'correct':''} ${training&&answered&&selected===i&&i!==q.answer?'wrong':''}" ${training&&answered?'disabled':''} data-${training?'quiz-answer':'exam-answer'}="${i}"><span class="letter">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>${training&&answered?`<div class="answer-explanation ${selected===q.answer?'':'bad'}"><b>${selected===q.answer?'✓ Risposta esatta':'✕ Risposta da rivedere'}</b><div style="margin-top:6px">${esc(q.why)}</div>${q.sourceUrl?`<div style="margin-top:9px;font-size:11px">${external(q.sourceUrl,'Verifica il riferimento istituzionale','')}</div>`:''}${q.authenticStem?'<div class="milano-source-caption">Testo della domanda: CCIAA Milano. Alternative e soluzione: elaborazione didattica.</div>':''}</div>`:''}</div>`;}
function renderQuizResult(){const g=quizSession;const correct=g.questions.filter((q,i)=>g.answers[i]===q.answer).length;const wrong=g.questions.length-correct;return `<div class="quiz-stage"><div class="result-banner"><div class="eyebrow">ALLENAMENTO COMPLETATO</div><h1>${correct>=g.questions.length*.8?'Ottimo lavoro!':'Ogni errore ti fa crescere.'}</h1><p>Hai risposto correttamente a ${correct} domande su ${g.questions.length}. Le risposte errate sono state aggiunte al ripasso.</p></div><div class="result-tiles"><div><b>${Math.round(correct/g.questions.length*100)}%</b><span>Precisione</span></div><div><b>${correct}</b><span>Risposte esatte</span></div><div><b>${wrong}</b><span>Da ripassare</span></div></div><div class="panel" style="margin-top:20px"><h3>Prossimo passo</h3><p class="muted" style="font-size:12px;line-height:1.8">Rileggi le spiegazioni e torna sui quesiti errati. Quando ti senti pronto, passa a una simulazione completa.</p><div style="display:flex;gap:10px;flex-wrap:wrap">${btn('Nuovo allenamento','quit-quiz')}${btn('Ripassa gli errori','go-errors','btn-outline')}${btn('Simula l’esame','go-exam','btn-outline')}</div></div></div>`;}
function renderExam(){if(examSession)return renderExamGame();const latest=data.examHistory.at(-1);return `${pageTitle('METTITI ALLA PROVA','Simulazione d’esame.','Una prova completa secondo il formato della Camera di Commercio di Milano: un timer, 40 quesiti e lo stesso criterio di punteggio pubblicato.')}
 <div class="hero" style="min-height:240px;grid-template-columns:1fr 31%;background:#1b3a36"><div><div class="eyebrow" style="color:#b7d8bd">PRONTO QUANDO VUOI</div><h1 style="font-size:2.65rem">40 domande.<br><em>40 minuti.</em></h1><p>20 quesiti di normativa e 20 di tecnica, estratti casualmente dal nostro archivio didattico. Le risposte sbagliate penalizzano il punteggio.</p></div><div class="hero-art" style="display:grid;place-items:center"><div style="font-family:Manrope;font-size:97px;font-weight:800;letter-spacing:-.12em;color:#d9ed99">40<span style="font-size:33px">′</span></div></div></div>
 <div class="section-heading"><h2>Le regole della prova</h2></div><div class="metrics" style="margin-top:0"><div class="metric"><div class="metric-top">Corretta</div><div class="metric-number" style="color:#3c966d">+0,50</div><div class="metric-caption">punti per risposta</div></div><div class="metric"><div class="metric-top">Errata</div><div class="metric-number" style="color:#c27659">−0,25</div><div class="metric-caption">punti per risposta</div></div><div class="metric"><div class="metric-top">Non risposta</div><div class="metric-number">0</div><div class="metric-caption">nessuna penalità</div></div><div class="metric"><div class="metric-top">Ammissione orale</div><div class="metric-number" style="font-size:23px">≥ 7/10</div><div class="metric-caption">media e ciascuna parte ≥ 6</div></div></div>
 <div class="two-col" style="margin-top:21px"><div class="panel"><h3>Una prova come quella camerale</h3><div class="summary-list" style="margin:18px 0">${['20 domande di normativa e 20 di tecnica','40 minuti totali, con contatore','Possibilità di lasciare risposte in bianco','Risultato per ciascuna parte e media complessiva','Soluzioni e spiegazioni dopo la consegna'].map((s,i)=>`<div class="summary-item"><span>${i+1}</span>${s}</div>`).join('')}</div><button class="btn btn-primary" data-action="start-exam">Inizia la simulazione →</button><p style="font-size:10px;color:#90a098;margin:13px 0 0">I quesiti sono didattici: la prova non replica il database riservato effettivamente estratto all’esame.</p></div><div class="panel"><h3>Il tuo storico</h3>${data.examHistory.length?`<div style="display:grid;gap:12px;margin-top:18px">${data.examHistory.slice(-4).reverse().map(x=>`<div class="learning-card"><div class="learning-icon">${x.passed?'✓':'↺'}</div><div><h4>${x.passed?'Obiettivo scritto raggiunto':'Scritto da migliorare'}</h4><p>${new Date(x.date).toLocaleDateString('it-IT')} · Norm. ${x.n}/10 · Tecn. ${x.t}/10</p></div></div>`).join('')}</div>`:`<div class="empty-state" style="padding:28px;border:0"><div class="empty-icon">◷</div><h3>Nessuna simulazione ancora</h3><p>La prima serve a capire da dove cominci. Non devi essere già preparato.</p></div>`}</div></div><div style="margin-top:18px;font-size:11px;color:#86978d">Fonte criteri: ${external(EXAM_RULES_URL,'Regolamento dell’esame CCIAA','')}</div>`;}
function examTime(){if(!examSession)return '40:00';const sec=Math.max(0,Math.ceil((examSession.deadline-Date.now())/1000));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function renderExamGame(){const g=examSession,q=g.questions[g.i],sel=g.answers[g.i];return `<div class="quiz-stage"><div class="question-top"><div><div class="eyebrow">SIMULAZIONE IN CORSO</div><h2 style="font-size:19px;margin:0">Domanda ${g.i+1}<span class="muted"> / 40</span></h2></div><div style="text-align:right"><small class="muted">TEMPO RESTANTE</small><div class="exam-timer" id="exam-timer">${examTime()}</div></div></div><div class="exam-meter quiz-meter"><span style="width:${(g.i+1)/40*100}%"></span></div>${questionCard(q,sel,false)}<div class="exam-dots">${g.questions.map((_,i)=>`<button class="exam-dot ${g.answers[i]!==null?'answered':''} ${i===g.i?'current':''}" title="Domanda ${i+1}" aria-label="Vai alla domanda ${i+1}" data-exam-jump="${i}"></button>`).join('')}</div><div class="quiz-controls"><button class="btn btn-outline" data-action="exam-prev" ${g.i===0?'disabled':''}>← Precedente</button><button class="btn btn-outline btn-sm" data-action="exam-clear">Lascia in bianco</button><span style="font-size:11px;color:#80958a">${g.answers.filter(x=>x!==null).length}/40 risposte</span>${g.i===39?btn('Consegna la prova','submit-exam','btn-primary'):btn('Successiva →','exam-next','btn-primary')}</div><div style="display:flex;justify-content:center;margin-top:17px"><button class="btn-link" data-action="submit-exam">Consegna prima del tempo</button></div></div>`;}
function renderExamResult(){const g=examSession;if(!g)return renderExam();const norm=g.questions.slice(0,20),tech=g.questions.slice(20);const score=(qq,offset)=>Math.max(0,qq.reduce((s,q,i)=>s+(g.answers[offset+i]===null?0:g.answers[offset+i]===q.answer?.5:-.25),0));const n=score(norm,0),t=score(tech,20),mean=(n+t)/2,passed=n>=6&&t>=6&&mean>=7;return `<div class="quiz-stage"><div class="result-banner ${passed?'':'fail'}"><div class="eyebrow">RISULTATO DELLA SIMULAZIONE</div><h1>${passed?'Obiettivo scritto raggiunto!':'Adesso sai cosa migliorare.'}</h1><p>${passed?'Hai raggiunto le soglie richieste per l’ammissione all’orale nella simulazione.':'Per superare lo scritto servono almeno 6/10 in ciascuna parte e una media minima di 7/10. Ripassa gli errori e riprova.'}</p></div><div class="result-tiles"><div><b>${n.toFixed(2).replace('.00','')}/10</b><span>Normativa</span></div><div><b>${t.toFixed(2).replace('.00','')}/10</b><span>Tecnica</span></div><div><b>${mean.toFixed(2).replace('.00','')}/10</b><span>Media</span></div></div><div class="panel" style="margin-top:20px"><h3>Analisi delle risposte</h3><div class="summary-list">${g.questions.map((q,i)=>`<div class="summary-item" style="border-bottom:1px solid #edf1ed;padding-bottom:10px"><span style="background:${g.answers[i]===q.answer?'#d7ead4':g.answers[i]===null?'#e6e9e4':'#fbe7df'};color:${g.answers[i]===q.answer?'#397250':'#a56c4f'}">${g.answers[i]===q.answer?'✓':g.answers[i]===null?'–':'×'}</span><div><b style="font-size:11px;color:#344c40">${i+1}. ${esc(q.question)}</b><div style="font-size:11px;margin-top:5px">${esc(q.why)}</div></div></div>`).join('')}</div><div class="article-toolbar">${btn('Nuova simulazione','reset-exam','btn-primary')}${btn('Ripassa gli errori','go-errors','btn-outline')}</div></div></div>`;}
function flashCards(){return allLessons.filter(l=>flashCategory==='all'||flashCategory==='again'&&data.flashAgain.includes(l.id)||l.category===flashCategory)}
function renderFlashcards(){const cards=flashCards();if(flashIndex>=cards.length)flashIndex=0;const card=cards[flashIndex];return `${pageTitle('RICHIAMO ATTIVO','Flashcard.','Prima prova a ricordare la risposta. Poi gira la scheda e verifica: il recupero attivo allena la memoria più della semplice rilettura.')}
 <div class="filters"><button class="chip ${flashCategory==='all'?'active':''}" data-flash-category="all">Tutte</button><button class="chip ${flashCategory==='normativa'?'active':''}" data-flash-category="normativa">Normativa</button><button class="chip ${flashCategory==='tecnica'?'active':''}" data-flash-category="tecnica">Tecnica</button><button class="chip ${flashCategory==='again'?'active':''}" data-flash-category="again">Da rivedere (${data.flashAgain.length})</button><span style="margin-left:auto;font-size:11px;color:#85948a">${data.flashKnown.length} concetti acquisiti</span></div>${!card?`<div class="empty-state"><h3>Nessuna scheda da rivedere</h3><p>Quando trovi un concetto difficile, premi «Da rivedere» sulla sua flashcard.</p><button class="btn btn-primary" data-flash-category="all">Vedi tutte le flashcard →</button></div>`:`<div class="flashcard-wrap"><div style="display:flex;justify-content:space-between;color:#85948a;font-size:11px;margin-bottom:11px"><span>${esc(card.moduleTitle)}</span><b>${flashIndex+1} / ${cards.length}</b></div><div class="flashcard ${flashFlipped?'flipped':''}" data-action="flip-flashcard" tabindex="0" role="button" aria-label="Gira la scheda"><div class="flashcard-inner"><div class="flash-face"><small>✦ RICORDA IL CONCETTO</small><h2>${esc(card.title)}</h2><small>Tocca la scheda per scoprire la risposta ↗</small></div><div class="flash-face back"><small>✓ LA RISPOSTA IN SINTESI</small><h2>${esc(card.key)}</h2><p>${esc(card.intro)}</p><small>Tocca per tornare alla domanda</small></div></div></div><div class="flashcard-actions"><button class="btn btn-outline" data-action="flash-prev">← Indietro</button><button class="btn btn-outline" data-action="flash-again">Da rivedere</button><button class="btn btn-soft" data-action="flash-known">✓ Lo so</button><button class="btn btn-primary" data-action="flash-next">Avanti →</button></div></div>`}`;}
function renderReview(){const savedLessons=allLessons.filter(l=>data.bookmarks.includes(l.id));const wrongQuestions=QUESTIONS.filter(q=>data.wrong.includes(q.id));const errors=reviewTab==='errors';return `${pageTitle('CONSOLIDA QUELLO CHE IMPARI','Il tuo ripasso.','Tutto ciò che vale la pena rivedere: domande sbagliate, lezioni preferite, appunti e dizionario essenziale.')}
 <div class="filters"><button class="chip ${errors?'active':''}" data-review-tab="errors">Errori (${wrongQuestions.length})</button><button class="chip ${reviewTab==='saved'?'active':''}" data-review-tab="saved">Preferiti (${savedLessons.length})</button><button class="chip ${reviewTab==='notes'?'active':''}" data-review-tab="notes">Appunti</button><button class="chip ${reviewTab==='glossary'?'active':''}" data-review-tab="glossary">Glossario (${GLOSSARY.length})</button></div>
 ${errors?(wrongQuestions.length?`<div class="study-banner" style="margin-bottom:20px"><div><b>Gli errori sono il tuo programma personalizzato</b><p>Riprova questi quesiti. Quando rispondi correttamente, li puoi togliere da questa lista.</p></div>${btn('Allenati sugli errori →','start-error-quiz','btn-primary btn-sm')}</div><div class="lesson-list">${wrongQuestions.map(q=>`<div class="panel" style="padding:20px"><div class="question-top" style="margin-bottom:8px"><small>${esc(moduleBy(q.module).title).toUpperCase()}</small><button class="btn-link" data-forget-wrong="${q.id}">Segna come acquisita ✓</button></div><h3 style="font-size:14px;margin:0 0 8px">${esc(q.question)}</h3><p class="muted" style="font-size:11px;line-height:1.7;margin:0">${esc(q.why)}</p></div>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">◇</div><h3>Nessun errore da ripassare</h3><p>Quando sbaglierai una domanda, la troverai qui con la spiegazione.</p><button class="btn btn-primary" data-nav="quiz">Allenati ora →</button></div>`):''}
 ${reviewTab==='saved'?(savedLessons.length?`<div class="lesson-list">${savedLessons.map(l=>`<button class="lesson-row" data-open-lesson="${l.mid}|${l.idx}"><span class="lesson-row-num">★</span><span class="lesson-row-main"><h4>${esc(l.title)}</h4><p>${esc(l.moduleTitle)}</p></span><span class="lesson-row-end">→</span></button>`).join('')}</div>`:`<div class="empty-state"><div class="empty-icon">☆</div><h3>Non hai ancora salvato lezioni</h3><p>Apri una lezione e premi “Salva per ripassare”.</p><button class="btn btn-primary" data-nav="library">Vai al programma →</button></div>`):''}
 ${reviewTab==='notes'?`<div class="two-col"><div class="review-note"><label for="general-notes">Appunti liberi</label><p class="muted" style="font-size:11px;margin:8px 0">Uno spazio per formule, dubbi o idee da ricordare.</p><textarea id="general-notes" placeholder="Scrivi qui i tuoi appunti generali...">${esc(data.generalNotes)}</textarea><p class="muted" style="font-size:10px;margin-top:9px">Salvataggio automatico nel browser.</p></div><div>${Object.entries(data.notes).filter(([_,v])=>v.trim()).length?Object.entries(data.notes).filter(([_,v])=>v.trim()).map(([lid,v])=>{const l=allLessons.find(x=>x.id===lid);return `<div class="review-note" style="margin-bottom:12px"><div class="eyebrow">${l?esc(l.moduleTitle):'Lezione'}</div><h3 style="font-size:13px">${l?esc(l.title):esc(lid)}</h3><p class="muted" style="white-space:pre-wrap;font-size:12px;line-height:1.8">${esc(v)}</p>${l?`<button class="btn-link" data-open-lesson="${l.mid}|${l.idx}">Apri lezione ↗</button>`:''}</div>`}).join(''):`<div class="empty-state"><p>Gli appunti scritti dentro le lezioni compariranno qui.</p></div>`}</div></div>`:''}
 ${reviewTab==='glossary'?`<div class="glossary-grid">${GLOSSARY.map(([a,b])=>`<div class="glossary-item"><b>${esc(a)}</b><p>${esc(b)}</p></div>`).join('')}</div>`:''}
 <div style="margin-top:35px;border-top:1px solid var(--border);padding-top:20px;display:flex;gap:10px;flex-wrap:wrap;align-items:center"><button class="btn btn-outline btn-sm" data-action="export-progress">↓ Esporta i miei progressi</button><label class="btn btn-outline btn-sm" style="cursor:pointer">↑ Importa progressi<input type="file" id="import-progress" accept="application/json,.json" style="display:none"></label><span style="font-size:10px;color:#8a988d">Salvati solo nel browser: esporta un backup se cambi dispositivo.</span></div>`;}
function renderSources(){return `${pageTitle('RIFERIMENTI E VERIFICHE','Le fonti ufficiali.','Materiali camerali e istituzionali selezionati per studiare su basi verificabili. Sono risorse esterne; controlla sempre gli aggiornamenti.')}
 <div class="study-banner" style="margin-bottom:22px"><div><b>Come sono costruite le domande degli esami scorsi</b><p>Milano pubblica una selezione di tracce senza opzioni e soluzioni. Roma rende disponibile una banca di quiz per materie, in una versione storica del 2014. Anche Venezia Rovigo pubblica raccolte camerali con soluzioni contrassegnate. I nostri quesiti ispirati a queste fonti sono <strong>rielaborazioni didattiche</strong>, con risposte e spiegazioni redatte per il sito: non sono copie integrali di compiti realmente estratti né una garanzia di domande identiche all’esame. I quiz “Focus Cremona” sono casi locali originali, non quesiti ufficiali precedenti.</p></div><div style="display:grid;gap:8px">${external(OFFICIAL_BANK_URL,'Archivio Milano')}${external(ROMA_BANK_URL,'Archivio Roma')}</div></div>
 <div class="module-grid">${SOURCES.map(s=>`<div class="resource-card"><span class="pill gray">${esc(s.type)}</span><h3>${esc(s.title)}</h3><p>${esc(s.detail)}</p>${external(s.url,'Apri la fonte','')}</div>`).join('')}</div><div class="panel" style="margin-top:25px"><h3>Come iscriversi all’esame, se parti da Cremona</h3><p style="font-size:12px;line-height:1.9;color:#6e8074">La Camera di Commercio di Milano Monza Brianza Lodi consente, per convenzione, l’iscrizione dei candidati residenti o con domicilio professionale nella circoscrizione di Cremona-Mantova-Pavia. Per la normativa lombarda attuale il percorso formativo prevede il corso riconosciuto di 150 ore per chi segue il nuovo standard del 2025 (salve situazioni transitorie o corsi riconosciuti di altre Regioni), oltre ai requisiti di titolo di studio. La procedura è online presso la Camera. Verifica requisiti e disponibilità prima di prenotare.</p><div class="mini-steps"><span class="step-tag">Diploma richiesto</span><span class="step-tag">Corso abilitante riconosciuto</span><span class="step-tag">Esame scritto + orale</span><span class="step-tag">Adempimenti per esercitare</span></div><p style="font-size:10px;line-height:1.7;color:#9aa69e;margin-top:18px">Ultima verifica delle fonti: 5 novembre 2026. Le norme e le modalità operative possono cambiare; prevalgono sempre testi vigenti, regolamenti e comunicazioni ufficiali. Questo sito è un ausilio didattico e non rilascia attestati né abilitazioni.</p></div>`;}
function renderOfficialArchive(){const tests=OFFICIAL_ARCHIVE_TESTS.filter(t=>archiveFilter==='all'||t.groupId===archiveFilter),totalDone=OFFICIAL_ARCHIVE_TESTS.filter(t=>data.officialDone.includes(String(t.sourceId))).length;return `${pageTitle('DOMANDE ORIGINALI DELLE CAMERE DI COMMERCIO','Le banche quiz ufficiali.',`Accedi direttamente a ${OFFICIAL_ARCHIVE_TESTS.length} batterie della Camera di Commercio di Roma, per un totale di ${OFFICIAL_ARCHIVE_TOTAL.toLocaleString('it-IT')} quesiti pubblicati. Aggiungi la selezione camerale di Milano e segna quelli già svolti.`)}
 <div class="metrics archive-metrics"><div class="metric"><div class="metric-top">Roma · batterie ufficiali</div><div class="metric-number">${OFFICIAL_ARCHIVE_TESTS.length}</div><div class="metric-caption">Quiz originali consultabili alla fonte</div></div><div class="metric"><div class="metric-top">Roma · domande pubblicate</div><div class="metric-number">${OFFICIAL_ARCHIVE_TOTAL.toLocaleString('it-IT')}</div><div class="metric-caption">Banca storica del 2014</div></div><div class="metric"><div class="metric-top">Batterie completate</div><div class="metric-number">${totalDone}<span class="muted" style="font-size:15px">/${OFFICIAL_ARCHIVE_TESTS.length}</span></div><div class="metric-caption">Progressi su questo dispositivo</div></div></div>
 <div class="study-banner" style="margin:23px 0"><div><b>Milano · selezione ufficiale delle domande scritte</b><p>La Camera di Commercio di Milano Monza Brianza Lodi pubblica una selezione di tracce realmente presenti nella propria banca d’esame, senza le tre alternative di risposta. L’accesso a ulteriori quesiti è riservato ai candidati registrati secondo le indicazioni della Camera.</p></div><div style="display:grid;gap:9px;align-content:center">${external('https://www.milomb.camcom.it/database-esami-selezione-domande-prove-scritte','Pagina della Camera')}${external(OFFICIAL_BANK_URL,'Apri il documento')}<button class="btn btn-primary btn-sm" data-nav="milanobank">Sfoglia tutte le ${MILANO_TRACES.length} domande nel manuale →</button></div></div>
 <div class="panel" style="padding:19px;margin-bottom:23px;border-left:4px solid var(--orange,#e58d36)"><b style="font-size:13px">Importante: queste sono banche camerali, non i fascicoli di un singolo esame.</b><p class="muted" style="font-size:12px;line-height:1.75;margin-bottom:0">Le batterie di Roma risalgono al 2014: alcune formulazioni o risposte potrebbero non riflettere più la normativa vigente. Le domande originali sono consultabili sul sito della Camera di Commercio; i quiz interni della nostra accademia sono invece rielaborazioni didattiche e sono contrassegnati come tali. Non esistono domande ufficiali specifiche su Cremona nel programma nazionale qui documentato.</p></div>
 <div class="section-heading"><div><h2>Roma · archivio completo per materia</h2><p>Apri le batterie originali nel sito istituzionale e spunta quelle già svolte.</p></div>${external('https://www.rm.camcom.it/pagina918_quiz-esame-mediatori-valido-dal-24-febbraio-2014.html','Fonte Roma')}</div>
 <div class="filters"><button class="chip ${archiveFilter==='all'?'active':''}" data-archive-filter="all">Tutte · ${OFFICIAL_ARCHIVE_TESTS.length}</button>${OFFICIAL_ARCHIVE_GROUPS.map(g=>`<button class="chip ${archiveFilter===g.id?'active':''}" data-archive-filter="${g.id}">${g.title} · ${g.tests.length}</button>`).join('')}</div>
 <div class="archive-list">${tests.map(t=>`<article class="archive-row"><div class="archive-main"><span class="archive-number">${String(OFFICIAL_ARCHIVE_TESTS.indexOf(t)+1).padStart(2,'0')}</span><div><span class="eyebrow">${esc(t.groupTitle)} · ${t.count} quesiti</span><h3>${esc(t.title)}</h3><small>Camera di Commercio di Roma · banca storica</small></div></div><div class="archive-actions"><button class="btn btn-sm ${data.officialDone.includes(String(t.sourceId))?'btn-soft':'btn-outline'}" data-official-done="${t.sourceId}">${data.officialDone.includes(String(t.sourceId))?'✓ Svolto':'○ Segna svolto'}</button><button class="btn btn-sm btn-primary" data-open-official="${t.sourceId}">Svolgi qui →</button>${external(t.url,'Apri fonte','btn btn-sm btn-outline')}</div></article>`).join('')}</div><div class="study-banner" style="margin-top:23px"><div><b>Vuoi esercitarti direttamente qui, con correzioni?</b><p>Le domande dell’allenamento interno sono rielaborazioni di quesiti camerali, con risposte commentate. Sono distinte dagli originali accessibili sopra.</p></div><button class="btn btn-primary" data-nav="quiz">Vai ai quiz interni →</button></div>`;}
function renderOfficialTest(id){const t=OFFICIAL_ARCHIVE_TESTS.find(x=>String(x.sourceId)===String(id));if(!t)return notFound();const done=data.officialDone.includes(String(t.sourceId));return `<div class="official-test-heading"><button class="back-button" data-nav="archive">← Tutte le batterie ufficiali</button><div class="eyebrow">CAMERA DI COMMERCIO DI ROMA · ${t.count} QUESITI · ARCHIVIO 2014</div><h1>${esc(t.title)}</h1><p>Le domande originali sono visualizzate qui direttamente dal sito della Camera di Commercio di Roma. Compila il test nel riquadro sottostante. Alcune risposte potrebbero essere superate dalla normativa attuale.</p><div class="official-test-toolbar"><button class="btn ${done?'btn-soft':'btn-outline'}" data-official-done="${t.sourceId}">${done?'✓ Batteria svolta':'○ Segna batteria come svolta'}</button>${external(t.url,'Apri su Roma CamCom','btn btn-outline') }</div></div><div class="official-embed-note"><strong>Quiz originale incorporato</strong><p>Se non compare sotto, il sito della Camera potrebbe impedire l’incorporamento: usa «Apri su Roma CamCom». Le risposte date nel riquadro non sono salvate dal nostro sito; puoi segnare la batteria come svolta dal pulsante in alto.</p></div><iframe class="official-test-frame" title="Quiz ufficiale Roma: ${esc(t.title)}" src="${esc(t.url)}" loading="eager" referrerpolicy="no-referrer-when-downgrade"></iframe><div class="study-banner" style="margin-top:19px"><div><b>Hai concluso questa batteria?</b><p>Segnala il completamento per tenere traccia del percorso su questo dispositivo.</p></div><button class="btn btn-primary" data-official-done="${t.sourceId}">${done?'✓ Già svolta · modifica':'Segna come svolta ✓'}</button></div>`;}
function milanoFilteredTraces(){
 const q=milanoSearch.toLocaleLowerCase('it').trim();
 return MILANO_TRACES.filter(t=>(milanoTopic==='all'||t.topic===milanoTopic)&&(milanoMode==='all'||(milanoMode==='verified'?t.verified:!t.verified))&&(!q||(`${t.question} ${t.topic}`).toLocaleLowerCase('it').includes(q)));
}
function renderMilanoBank(){
 const list=milanoFilteredTraces(),size=25,pages=Math.max(1,Math.ceil(list.length/size));
 milanoPage=Math.max(0,Math.min(milanoPage,pages-1));
 const rows=list.slice(milanoPage*size,(milanoPage+1)*size);
 return `${pageTitle('CAMERA DI COMMERCIO DI MILANO','Tutte le tracce pubblicate.','Banca originale Milano Monza Brianza Lodi: studia le domande del documento camerale, cerca per materia e allenati sulle risposte motivate.')}
 <div class="milano-intro"><strong>Tracce ufficiali, risposte didattiche</strong><p>La Camera di Commercio pubblica soltanto una <b>selezione</b> di domande della propria banca, senza opzioni né soluzioni. Abbiamo trascritto tutti i quesiti riconoscibili del documento di 26 pagine. Le alternative e le correzioni presenti qui sono elaborate per studiare: <b>non sono il correttore ufficiale della Camera</b>. Per le tracce non ancora controllate trovi solo il testo, senza soluzioni inventate. Alcuni quesiti citano terminologie precedenti alle modifiche normative più recenti.</p><div style="display:flex;gap:9px;flex-wrap:wrap;margin-top:15px"><button class="btn btn-primary btn-sm" data-action="start-milano-quiz">Allenati con le ${MILANO_VERIFIED_TOTAL} domande corrette →</button>${external(MILANO_PDF_URL,'Apri PDF della Camera','btn btn-outline btn-sm')}</div></div>
 <div class="milano-stats"><div class="milano-stat"><b>${MILANO_TRACES.length}</b><small>Tracce nel documento pubblico, importate nel sito</small></div><div class="milano-stat"><b>${MILANO_VERIFIED_TOTAL}</b><small>Nei quiz: tre alternative e risposta motivata</small></div><div class="milano-stat"><b>${MILANO_UNVERIFIED_TOTAL}</b><small>In consultazione, in attesa di verifica della soluzione</small></div></div>
 <div class="milano-toolbar"><label>Cerca nelle tracce<input id="milano-search" type="search" placeholder="Es. usufrutto, estimo, condominio..." autocomplete="off" value="${esc(milanoSearch)}"></label><label>Materia<select id="milano-topic"><option value="all">Tutte le materie</option>${MILANO_TOPICS.map(t=>`<option value="${esc(t)}" ${milanoTopic===t?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label>Stato della risposta<select id="milano-mode"><option value="all" ${milanoMode==='all'?'selected':''}>Tutte</option><option value="verified" ${milanoMode==='verified'?'selected':''}>Con risposta motivata</option><option value="pending" ${milanoMode==='pending'?'selected':''}>In attesa di verifica</option></select></label></div>
 <p class="muted" style="font-size:11px;margin:10px 0 17px">${list.length} tracce trovate · Pagina ${milanoPage+1} di ${pages}</p>
 <div class="milano-list">${rows.length?rows.map(t=>`<article class="milano-card"><div class="milano-card-head"><small>${esc(t.topic)} · #${t.line}</small>${tag(t.verified?'✓ Risposta motivata':'In attesa di verifica',t.verified?'official':'gray')}</div><h3>${esc(t.question)}</h3>${t.verified?`<details><summary>Mostra la soluzione spiegata</summary><p><strong>Risposta:</strong> ${esc(t.correct)}</p><p>${esc(t.explanation)}</p>${t.sourceUrl?external(t.sourceUrl,'Controlla il riferimento',''):''}<p class="milano-source-caption">Le opzioni e la soluzione sono state ricostruite a fini didattici.</p></details>`:`<div class="milano-pending">Il testo proviene dal PDF della Camera; non abbiamo ancora una soluzione abbastanza verificata per assegnare un punteggio.</div><div style="margin-top:10px"><button class="btn btn-outline btn-sm" data-open-module="${esc(t.module)}">Studia la materia →</button></div>`}</article>`).join(''):'<div class="empty-state">Nessuna domanda corrisponde ai filtri.</div>'}</div>
 <div class="milano-pagination"><button class="btn btn-outline btn-sm" data-milano-page="-1" ${milanoPage===0?'disabled':''}>← Precedente</button><span>${list.length?milanoPage*size+1:0}–${Math.min((milanoPage+1)*size,list.length)} di ${list.length} tracce</span><button class="btn btn-primary btn-sm" data-milano-page="1" ${milanoPage>=pages-1?'disabled':''}>Successiva →</button></div>`;
}
function notFound(){return `<div class="empty-state"><h2>Pagina non trovata</h2><button class="btn btn-primary" data-nav="home">Torna alla home</button></div>`;}
function render(scrollToTop=false){const {view,id,idx}=currentRoute();navActive(view);const root=$('#view');root.innerHTML=({home:renderHome,library:renderLibrary,module:()=>renderModule(id),lesson:()=>renderLesson(id,idx),quiz:renderQuiz,exam:()=>examSession?.finished?renderExamResult():renderExam(),flashcards:renderFlashcards,review:renderReview,sources:renderSources,archive:renderOfficialArchive,milanobank:renderMilanoBank,officialtest:()=>renderOfficialTest(id)}[view]||notFound)();document.title=`${({home:'Home',library:'Programma',module:moduleBy(id)?.title,lesson:lessonBy(id,idx)?.title,quiz:'Quiz',exam:'Simulazione',flashcards:'Flashcard',review:'Ripasso',sources:'Fonti ufficiali',archive:'Banche ufficiali',milanobank:'Banca Milano',officialtest:'Quiz ufficiale Roma'}[view]||'Patentino')} — Patentino`;if(scrollToTop)window.scrollTo({top:0,behavior:'instant'});}
function startQuiz(errorsOnly=false){let pool=categoryQuestions(quizSubject,quizModule,quizOrigin);if(errorsOnly||quizSize==='errors')pool=pool.filter(q=>data.wrong.includes(q.id));if(!pool.length){toast('Nessun quesito disponibile con questi filtri');return}const count=errorsOnly||quizSize==='errors'?Math.min(pool.length,20):Math.min(Number(quizSize),pool.length);const qs=shuffle(pool).slice(0,count);quizSession={questions:qs,answers:Array(qs.length).fill(null),i:0,recorded:false};navigate('quiz');}
function startModuleMiniQuiz(id){const all=QUESTIONS.filter(q=>q.module===id),official=all.filter(q=>['milano','roma','venezia-rovigo'].includes(questionOrigin(q)));const prioritized=shuffle(official).concat(shuffle(all.filter(q=>!official.includes(q))));if(!prioritized.length){toast('Nessuna domanda disponibile per questo modulo');return}const qs=prioritized.slice(0,Math.min(5,prioritized.length));quizSession={questions:qs,answers:Array(qs.length).fill(null),i:0,recorded:false,miniModule:id};navigate('quiz');}
function quizAnswer(i){if(!quizSession||quizSession.answers[quizSession.i]!==null)return;const q=quizSession.questions[quizSession.i];quizSession.answers[quizSession.i]=i;if(i!==q.answer&&!data.wrong.includes(q.id))data.wrong.push(q.id);save();render();}
function quizNext(){if(!quizSession)return;if(quizSession.i<quizSession.questions.length-1){quizSession.i++;render(true)}else{if(!quizSession.recorded){const correct=quizSession.questions.filter((q,i)=>quizSession.answers[i]===q.answer).length;data.quizHistory.push({date:new Date().toISOString(),count:quizSession.questions.length,correct});quizSession.recorded=true;save()}quizSession.i=quizSession.questions.length;render(true)}}
function startExam(){const eligible=QUESTIONS.filter(q=>['milano','roma','venezia-rovigo'].includes(questionOrigin(q)));const pick=(category)=>{const pool=eligible.filter(q=>moduleBy(q.module).category===category),milan=shuffle(pool.filter(q=>q.authenticStem)),other=shuffle(pool.filter(q=>!q.authenticStem));return milan.slice(0,20).concat(other.slice(0,Math.max(0,20-milan.length)))};const n=pick('normativa'),t=pick('tecnica');examSession={questions:[...n,...t],answers:Array(40).fill(null),i:0,deadline:Date.now()+40*60000,finished:false,recorded:false};startTicker();navigate('exam');}
function startTicker(){clearInterval(examTicker);examTicker=setInterval(()=>{if(!examSession||examSession.finished){clearInterval(examTicker);return}const target=$('#exam-timer');if(target){target.textContent=examTime();target.classList.toggle('urgent',examSession.deadline-Date.now()<5*60000)}if(Date.now()>=examSession.deadline)finishExam()},1000)}
function finishExam(){if(!examSession||examSession.finished)return;examSession.finished=true;clearInterval(examTicker);const score=(from,to)=>Math.max(0,examSession.questions.slice(from,to).reduce((s,q,i)=>s+(examSession.answers[from+i]===null?0:examSession.answers[from+i]===q.answer?.5:-.25),0));const n=score(0,20),t=score(20,40);data.examHistory.push({date:new Date().toISOString(),count:40,n,t,passed:n>=6&&t>=6&&(n+t)/2>=7});for(let i=0;i<40;i++){const q=examSession.questions[i];if(examSession.answers[i]!==null&&examSession.answers[i]!==q.answer&&!data.wrong.includes(q.id))data.wrong.push(q.id)}save();render();}
function flashMove(delta){const cards=flashCards();flashIndex=cards.length?(flashIndex+delta+cards.length)%cards.length:0;flashFlipped=false;render()}
function toggleFrom(arr,id){const i=arr.indexOf(id);if(i>=0)arr.splice(i,1);else arr.push(id);save();render()}
document.addEventListener('click',e=>{
 const mini=e.target.closest('[data-mini-quiz]');if(mini){startModuleMiniQuiz(mini.dataset.miniQuiz);return}
 const opentest=e.target.closest('[data-open-official]');if(opentest){navigate('officialtest',opentest.dataset.openOfficial);return}
 const done=e.target.closest('[data-official-done]');if(done){toggleFrom(data.officialDone,done.dataset.officialDone);return}
 const page=e.target.closest('[data-milano-page]');if(page){milanoPage+=Number(page.dataset.milanoPage);render();return}
 const archive=e.target.closest('[data-archive-filter]');if(archive){archiveFilter=archive.dataset.archiveFilter;render();return}
 const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}
 const openM=e.target.closest('[data-open-module]');if(openM){navigate('module',openM.dataset.openModule);return}
 const openL=e.target.closest('[data-open-lesson]');if(openL){const [mid,idx]=openL.dataset.openLesson.split('|');navigate('lesson',mid,idx);return}
 const lib=e.target.closest('[data-lib-filter]');if(lib){libraryFilter=lib.dataset.libFilter;render();return}
 const cat=e.target.closest('[data-filter-category]');if(cat){libraryFilter=cat.dataset.filterCategory==='normativa'?'diritto':'immobiliare';navigate('library');return}
 const size=e.target.closest('[data-quiz-size]');if(size){quizSize=size.dataset.quizSize==='errors'?'errors':Number(size.dataset.quizSize);render();return}
 const qAns=e.target.closest('[data-quiz-answer]');if(qAns){quizAnswer(Number(qAns.dataset.quizAnswer));return}
 const eAns=e.target.closest('[data-exam-answer]');if(eAns&&examSession&&!examSession.finished){const a=Number(eAns.dataset.examAnswer);examSession.answers[examSession.i]=examSession.answers[examSession.i]===a?null:a;render();return}
 const jump=e.target.closest('[data-exam-jump]');if(jump&&examSession){examSession.i=Number(jump.dataset.examJump);render();return}
 const review=e.target.closest('[data-review-tab]');if(review){reviewTab=review.dataset.reviewTab;render();return}
 const forget=e.target.closest('[data-forget-wrong]');if(forget){data.wrong=data.wrong.filter(id=>id!==forget.dataset.forgetWrong);save();render();return}
 const flash=e.target.closest('[data-flash-category]');if(flash){flashCategory=flash.dataset.flashCategory;flashIndex=0;flashFlipped=false;render();return}
 const complete=e.target.closest('[data-toggle-complete]');if(complete){toggleFrom(data.completed,complete.dataset.toggleComplete);toast(data.completed.includes(complete.dataset.toggleComplete)?'Lezione completata!':'Lezione segnata come da studiare');return}
 const bookmark=e.target.closest('[data-toggle-bookmark]');if(bookmark){toggleFrom(data.bookmarks,bookmark.dataset.toggleBookmark);toast('Preferiti aggiornati');return}
 const action=e.target.closest('[data-action]');if(!action)return;switch(action.dataset.action){
  case 'go-library':navigate('library');break;
  case 'go-cremona-quiz':quizSession=null;quizOrigin='cremona';quizModule='all';quizSubject='all';quizSize=20;navigate('quiz');break;
  case 'go-exam':quizSession=null;navigate('exam');break;
  case 'go-errors':quizSession=null;reviewTab='errors';navigate('review');break;
  case 'quiz-module':quizSession=null;quizModule=action.dataset.moduleId;quizSubject='all';navigate('quiz');break;
  case 'start-quiz':startQuiz();break;
  case 'start-milano-quiz':quizSession=null;quizOrigin='milano';quizSubject='all';quizModule='all';quizSize=50;navigate('quiz');break;
  case 'start-official-quiz':navigate('officialtest',officialSessionId);break;
  case 'start-error-quiz':quizSubject='all';quizModule='all';quizOrigin='all';quizSize='errors';startQuiz(true);break;
  case 'quiz-next':quizNext();break;
  case 'quit-quiz':quizSession=null;render();break;
  case 'start-exam':startExam();break;
  case 'exam-next':if(examSession){examSession.i=Math.min(39,examSession.i+1);render(true)}break;
  case 'exam-prev':if(examSession){examSession.i=Math.max(0,examSession.i-1);render(true)}break;
  case 'exam-clear':if(examSession){examSession.answers[examSession.i]=null;render()}break;
  case 'submit-exam':finishExam();break;
  case 'reset-exam':examSession=null;render();break;
  case 'flip-flashcard':flashFlipped=!flashFlipped;render();break;
  case 'flash-next':flashMove(1);break;
  case 'flash-prev':flashMove(-1);break;
  case 'flash-again':{const id=flashCards()[flashIndex]?.id;if(id&&!data.flashAgain.includes(id))data.flashAgain.push(id);data.flashKnown=data.flashKnown.filter(x=>x!==id);save();flashMove(1);toast('Scheda aggiunta al ripasso');break}
  case 'flash-known':{const id=flashCards()[flashIndex]?.id;if(id&&!data.flashKnown.includes(id))data.flashKnown.push(id);data.flashAgain=data.flashAgain.filter(x=>x!==id);save();flashMove(1);break}
  case 'export-progress':{const blob=new Blob([JSON.stringify({app:'patentino-academy',version:1,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='patentino-progressi.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup scaricato');break}
 }
});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='milano-topic'){milanoTopic=t.value;milanoPage=0;render()}if(t.id==='milano-mode'){milanoMode=t.value;milanoPage=0;render()}if(t.id==='official-session-select'){officialSessionId=t.value}if(t.id==='quiz-subject'){quizSubject=t.value;quizModule='all';render()}if(t.id==='quiz-module'){quizModule=t.value;render()}if(t.id==='quiz-origin'){quizOrigin=t.value;render()}if(t.id==='import-progress'&&t.files?.[0]){try{const raw=JSON.parse(await t.files[0].text());if(raw.app!=='patentino-academy'||!raw.data||!Array.isArray(raw.data.completed))throw Error('Formato non valido');if(!confirm('Importare questo backup? I progressi attuali su questo dispositivo verranno sostituiti.'))return;const incoming=raw.data;for(const k of Object.keys(data))if(Object.hasOwn(incoming,k))data[k]=incoming[k];save();toast('Progressi importati');render()}catch{toast('File non valido: usa un backup di Patentino.')}}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='milano-search'){const caret=t.selectionStart;milanoSearch=t.value;milanoPage=0;render();const next=$('#milano-search');next?.focus();next?.setSelectionRange(caret,caret)}if(t.id==='module-search'){libraryQuery=t.value;const pos=t.selectionStart;const area=$('.module-grid');const filtered=MODULES.filter(m=>(m.id!=='cremona'&&(libraryFilter==='all'||sectorOf(m)===libraryFilter))&&(`${m.title} ${m.description} ${m.lessons.map(l=>l.title).join(' ')}`).toLowerCase().includes(libraryQuery.toLowerCase()));if(area)area.innerHTML=filtered.map(m=>{const done=m.lessons.filter((_,i)=>data.completed.includes(`${m.id}:${i}`)).length;return `<article class="module-card" data-open-module="${m.id}" role="button"><div class="module-card-top"><span class="module-num">MODULO ${String(MODULES.indexOf(m)+1).padStart(2,'0')}</span><span class="module-symbol">${m.icon}</span></div><h3>${esc(m.title)}</h3><p>${esc(m.description)}</p><div class="module-footer"><span>${tag(categoryLabel(m.category),m.category==='normativa'?'':'blue')}</span><span>${done}/${m.lessons.length} lezioni</span><div class="tiny-track"><span style="width:${done/m.lessons.length*100}%"></span></div></div></article>`}).join('')||'<div class="empty-state">Nessun argomento trovato.</div>'}if(t.dataset.noteLesson!==undefined){data.notes[t.dataset.noteLesson]=t.value;save()}if(t.id==='general-notes'){data.generalNotes=t.value;save()}});
window.addEventListener('hashchange',()=>render(true));
const searchBox=$('#search-modal');$('#global-search-trigger').addEventListener('click',()=>{searchBox.classList.remove('hidden');$('#global-search').focus();searchResults('')});$('#close-search').addEventListener('click',()=>searchBox.classList.add('hidden'));searchBox.addEventListener('click',e=>{if(e.target===searchBox)searchBox.classList.add('hidden')});$('#global-search').addEventListener('input',e=>searchResults(e.target.value));document.addEventListener('keydown',e=>{if(e.key==='Escape')searchBox.classList.add('hidden');if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchBox.classList.remove('hidden');$('#global-search').focus()}});
function searchResults(q){const v=q.toLowerCase().trim();const items=allLessons.filter(l=>!v||(`${l.title} ${l.moduleTitle} ${l.intro} ${l.detail}`).toLowerCase().includes(v)).slice(0,12);$('#search-results').innerHTML=items.length?items.map(l=>`<button class="search-result" data-search-open="${l.mid}|${l.idx}"><b>${esc(l.title)}</b><small>${esc(l.moduleTitle)}</small></button>`).join(''):`<div class="empty-state">Nessuna lezione trovata.</div>`}
$('#search-results').addEventListener('click',e=>{const item=e.target.closest('[data-search-open]');if(item){const [mid,idx]=item.dataset.searchOpen.split('|');searchBox.classList.add('hidden');navigate('lesson',mid,idx)}});
$('#today-label').textContent=new Intl.DateTimeFormat('it-IT',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
if(!location.hash)history.replaceState(null,'','#/home');render(true);
